// NewDispatch.sv — 后端派遣级：把重命名后的 6 条 uop 派往 17 个发射队列（IQ）。
//
// 位置：Rename 之后、IssueQueue 之前，与 Rob / LSQ 的入队握手同拍完成。
// 每拍从 Rename 收 6 条 uop（io_fromRename），给每条选一个 IQ，再把 34 个 IQ
// 入队口（17 个 IQ × 每 IQ 2 口）各自的 payload 选出来；同时把同一批 uop 送进
// Rob（io_enqRob）和 LSQ（io_toMem_lsqEnqIO）。
//
// 核心机制三层：
//   1. 选队列：按 fuType 把 uop 归到 10 个「多队列组」或 6 个「单队列组」。
//      多队列组按各 exu 的 IQValidNumVec（占用数）排序，取最空的那个；同一拍里
//      第 k 条要同组的 uop 取第 (k % iqNum) 名，避免 6 条挤同一个 IQ。
//   2. 记选择：uopSelIQ[lane][iq] 是个**不复位**的寄存器，在 toRenameAllFire 那
//      拍装入新选择，之后逐条 fire 清位。
//   3. 发 payload：uopSelIQMatrix 做前缀计数，第 iq 列上计到 (n+1) 的 lane 就是
//      该 IQ 第 n 个入队口的来源，用 PriorityMux 把 6 条 lane 选成 34 份 payload。
//
// ★本文件当前是「骨架 + 已追清的逻辑」，不是完成的重写★。已实现/未实现的边界
// 见节 3 wrapper 头上的「未追清 / 未实现清单」。
//
// golden 对照：G1-canonical/golden-rtl/NewDispatch.sv（100983 行，单变体）。
// 机械派生区（端口表 / dyninst_t）由 scripts/gen_newdispatch.py 从 golden 生成。
// 本文件导航（共 8370 行；按"一个 golden 模块一个文件"的规范不拆分，用下面的分节定位）：
//   L47    节 1】newdispatch_pkg —— 派遣拓扑表与 payload 类型
//   L63    节 1.1】多队列 FU 组表
//   L65    每组三件事：
//   L118   节 1.2】单队列 FU 组表
//   L136   节 1.3】dyninst_t —— 派遣级搬运的 uop payload
//   L138   180 个 leaf 是 golden 四个 payload bundle 的并集，且**无位宽冲突**：
//   L337   节 2】xs_NewDispatch_core —— 可读核
//   L365   节 2.1】fuType 归组
//   L367   golden: fuTypeOH_<lane>_<g> = (fuType[b1]|fuType[b2]|...) & rena
//   L382   节 2.2】compareMatrix / IQSort —— 按占用数给同组 IQ 排名
//   L384   compareMatrix[g][i][j] = 「第 i 个 exu 比第 j 个空」
//   L419   节 2.3】minIQSel —— 第 lane 条 uop 在本组里取第 (lane % iqNum) 名
//   L421   这一步是「同拍内分散」：6 条 lane 若都是 alu，就分别取第 0/1/2/3/0/1 名，
//   L435   节 2.4】popFuTypeOH —— 本 lane 之前有几条 uop 也要进同一组
//   L437   golden: popFuTypeOH_<lane>_<g> = PopCount(fuTypeOH[0..lane-1][g]
//   L451   节 2.5】uopSelIQ —— 不复位的选择寄存器，两个写源，装入优先于清除
//   L453   golden 展开
//   L498   节 2.6】uopSelIQMatrix / uopBlockByIQ —— 前缀计数定「第几个入队口」
//   L500   uopSelIQMatrix[lane][iq] = PopCount(uopSelIQ[0..lane][iq])
//   L526   节 3】NewDispatch —— 与 golden 逐位同名的 wrapper
//   L528   端口表由 scripts/gen_newdispatch.py 从 golden 原文派生，顺序/方向/位宽逐字一致
//

// ---------------------------------------------------------------------------
// 【节 1】newdispatch_pkg —— 派遣拓扑表与 payload 类型
// ---------------------------------------------------------------------------
package newdispatch_pkg;

  localparam int RENAME_W = 6;   // 每拍从 Rename 收几条 uop
  localparam int IQ_NUM   = 17;  // 发射队列数（golden 实测：uopSelIQ 是 6×17）
  localparam int IQ_ENQ   = 34;  // IQ 入队口总数；实测每个 IQ 都是 numEnq=2
  // exuNum：golden 端口表里只剩 23 个 io_IQValidNumVec，索引 0-6 / 8-16 / 18-24
  // —— 7 和 17 从没出现在任何 compareMatrix 里，被 firtool DCE 掉了。所以从 golden
  // 只能测到 exuNum ≥ 25；这里取 25 让核的下标与 golden 端口号直接对齐。
  localparam int EXU_NUM  = 25;
  localparam int MULTI_G  = 10;  // 多队列 FU 组数
  localparam int SINGLE_G = 6;   // 单队列 FU 组数
  localparam int FUTYPE_W = 35;  // fuType 位宽（FuType 共 35 种）

  // -------------------------------------------------------------------------
  // 【节 1.1】多队列 FU 组表（10 组）—— 全部来自 golden 实测，不是 Chisel 推断
  // -------------------------------------------------------------------------
  // 每组三件事：
  //   FU_BITS  这组认哪些 fuType 位（golden: fuTypeOH_<lane>_<g> 的或项）
  //   EXU_IDX  排序时比哪几个 io_IQValidNumVec（golden: compareMatrix_<g>_i_j）
  //   IQ_IDX   排完序后可以落到哪几个 IQ（golden: minIQSel_<g>_0_<iq> 非常数项）
  // 组序 = golden 里 minIQSelAll_<g> 的下标，实测为：
  //   0 jmp_brh  1 alu  2 mul_bku  3 falu_fmac  4 fdiv
  //   5 ldu      6 sta_mou  7 vialuFix_vfma  8 vfalu  9 vldu_vstu
  localparam int G_IQNUM [MULTI_G] = '{3, 4, 2, 3, 2, 3, 2, 2, 2, 2};

  // EXU_IDX / IQ_IDX 用定长 4 列，实际只取前 G_IQNUM[g] 个（4 = alu 的 iqNum 最大值）
  localparam int G_EXU [MULTI_G][4] = '{
    '{ 1,  3,  5,  0},   // jmp_brh       exu 1,3,5
    '{ 0,  2,  4,  6},   // alu           exu 0,2,4,6
    '{ 0,  2,  0,  0},   // mul_bku       exu 0,2   （与 alu 共用 0/2 的比较结果）
    '{ 8, 10, 12,  0},   // falu_fmac     exu 8,10,12
    '{ 9, 11,  0,  0},   // fdiv          exu 9,11
    '{20, 21, 22,  0},   // ldu           exu 20,21,22
    '{18, 19,  0,  0},   // sta_mou       exu 18,19
    '{13, 15,  0,  0},   // vialuFix_vfma exu 13,15
    '{14, 16,  0,  0},   // vfalu         exu 14,16
    '{23, 24,  0,  0}};  // vldu_vstu     exu 23,24

  localparam int G_IQ [MULTI_G][4] = '{
    '{ 0,  1,  2,  0},   // jmp_brh       -> IQ 0,1,2
    '{ 0,  1,  2,  3},   // alu           -> IQ 0,1,2,3
    '{ 0,  1,  0,  0},   // mul_bku       -> IQ 0,1
    '{ 4,  5,  6,  0},   // falu_fmac     -> IQ 4,5,6
    '{ 4,  5,  0,  0},   // fdiv          -> IQ 4,5
    '{12, 13, 14,  0},   // ldu           -> IQ 12,13,14
    '{10, 11,  0,  0},   // sta_mou       -> IQ 10,11
    '{ 7,  8,  0,  0},   // vialuFix_vfma -> IQ 7,8
    '{ 7,  8,  0,  0},   // vfalu         -> IQ 7,8（与 vialuFix_vfma 同 IQ，不同 exu）
    '{15, 16,  0,  0}};  // vldu_vstu     -> IQ 15,16

  // 每组认的 fuType 位，做成 35 位掩码（一位一个 FuType id）
  // FuType id: 0 jmp 1 brh 2 i2f 3 i2v 4 f2v 5 csr 6 alu 7 mul 8 div 9 fence
  //           10 bku 11 falu 12 fmac 13 fcvt 14 fDivSqrt 15 ldu 16 stu 17 mou
  //           18 vipu 19 vialuF 20 vppu 21 vimac 22 vidiv 23 vfpu 24 vfalu
  //           25 vfma 26 vfdiv 27 vfcvt 28 vsetiwi 29 vsetiwf 30 vsetfwf
  //           31 vldu 32 vstu 33 vsegldu 34 vsegstu
  localparam logic [FUTYPE_W-1:0] G_FUMASK [MULTI_G] = '{
    (35'b1 <<  0) | (35'b1 <<  1),                  // jmp_brh       jmp|brh
    (35'b1 <<  6),                                  // alu           alu
    (35'b1 <<  7) | (35'b1 << 10),                  // mul_bku       mul|bku
    (35'b1 << 11) | (35'b1 << 12),                  // falu_fmac     falu|fmac
    (35'b1 << 14),                                  // fdiv          fDivSqrt
    (35'b1 << 15),                                  // ldu           ldu
    (35'b1 << 16) | (35'b1 << 17),                  // sta_mou       stu|mou
    (35'b1 << 19) | (35'b1 << 25),                  // vialuFix_vfma vialuF|vfma
    (35'b1 << 24),                                  // vfalu         vfalu
    (35'b1 << 31) | (35'b1 << 32)};                 // vldu_vstu     vldu|vstu

  // -------------------------------------------------------------------------
  // 【节 1.2】单队列 FU 组表（6 组）—— 这些 fuType 只有一个 IQ 能收，不用排序
  // -------------------------------------------------------------------------
  localparam logic [FUTYPE_W-1:0] S_FUMASK [SINGLE_G] = '{
    (35'b1 <<  2) | (35'b1 <<  3) | (35'b1 << 28) | (35'b1 << 29),  // i2f|i2v|vsetiwi|vsetiwf
    (35'b1 <<  4) | (35'b1 << 13),                                  // f2v|fcvt
    (35'b1 <<  5) | (35'b1 <<  8) | (35'b1 <<  9),                  // csr|div|fence
    (35'b1 << 18) | (35'b1 << 20) | (35'b1 << 21)
                  | (35'b1 << 27) | (35'b1 << 30),                  // vipu|vppu|vimac|vfcvt|vsetfwf
    (35'b1 << 22) | (35'b1 << 26),                                  // vidiv|vfdiv
    (35'b1 << 33) | (35'b1 << 34)};                                 // vsegldu|vsegstu

  // 单队列组落到哪个 IQ（golden: uopSelIQ_0_<iq> 里引用 fuTypeOHSingle_0_<s> 的位置）
  localparam int S_IQ [SINGLE_G] = '{2, 4, 3, 7, 9, 15};

  // 注意 fuType 23（vfpu）不属于任何组 —— golden 里没有任何 fuTypeOH 引用它。
  // 不是漏抄：KunminghuV2Config 下没有 exu 声明 vfpu。

  // -------------------------------------------------------------------------
  // 【节 1.3】dyninst_t —— 派遣级搬运的 uop payload
  // -------------------------------------------------------------------------
  // 180 个 leaf 是 golden 四个 payload bundle 的并集，且**无位宽冲突**：
  //   io_toIssueQueues_*_bits_*      180 leaf（超集）
  //   io_fromRename_*_bits_*         134 leaf ⊂ 超集
  //   io_enqRob_req_*_bits_*          63 leaf ⊂ 超集
  //   io_toMem_lsqEnqIO_req_*_bits_*  53 leaf ⊂ 超集
  // 也就是说：NewDispatch 从 Rename 收 134 个字段，往 IQ 发 180 个 ——
  // **多出来的 46 个字段就是本模块的全部「增值」**（busy table 的 srcState /
  // srcLoadDependency、RegCacheTagTable 的 useRegCache/regCacheIdx、
  // LsqEnqCtrl 的 lqIdx/sqIdx、mdp 的 storeSetHit/ssid/waitForRobIdx、
  // 以及 singleStep / isDropAmocasSta / replayInst / debugInfo 时间戳）。
  // 而这 46 个字段**全部依赖本仓尚未实现的 7 个子模块**，见文件头清单。
  // BEGIN GENERATED(DYNINST_T)
typedef struct packed {
  logic [31:0]   instr;
  logic [49:0]   pc;
  logic [9:0]    foldpc;
  logic          exceptionVec_0;
  logic          exceptionVec_1;
  logic          exceptionVec_2;
  logic          exceptionVec_3;
  logic          exceptionVec_4;
  logic          exceptionVec_5;
  logic          exceptionVec_6;
  logic          exceptionVec_7;
  logic          exceptionVec_8;
  logic          exceptionVec_9;
  logic          exceptionVec_10;
  logic          exceptionVec_11;
  logic          exceptionVec_12;
  logic          exceptionVec_13;
  logic          exceptionVec_14;
  logic          exceptionVec_15;
  logic          exceptionVec_16;
  logic          exceptionVec_17;
  logic          exceptionVec_18;
  logic          exceptionVec_19;
  logic          exceptionVec_20;
  logic          exceptionVec_21;
  logic          exceptionVec_22;
  logic          exceptionVec_23;
  logic          isFetchMalAddr;
  logic          hasException;
  logic [3:0]    trigger;
  logic          preDecodeInfo_valid;
  logic          preDecodeInfo_isRVC;
  logic [1:0]    preDecodeInfo_brType;
  logic          preDecodeInfo_isCall;
  logic          preDecodeInfo_isRet;
  logic          pred_taken;
  logic          crossPageIPFFix;
  logic          ftqPtr_flag;
  logic [5:0]    ftqPtr_value;
  logic [3:0]    ftqOffset;
  logic          satpFlushFirstFetchFault;
  logic [3:0]    srcType_0;
  logic [3:0]    srcType_1;
  logic [3:0]    srcType_2;
  logic [3:0]    srcType_3;
  logic [3:0]    srcType_4;
  logic [5:0]    ldest;
  logic [34:0]   fuType;
  logic [8:0]    fuOpType;
  logic          rfWen;
  logic          fpWen;
  logic          vecWen;
  logic          v0Wen;
  logic          vlWen;
  logic          isXSTrap;
  logic          waitForward;
  logic          blockBackward;
  logic          flushPipe;
  logic          canRobCompress;
  logic [3:0]    selImm;
  logic [31:0]   imm;
  logic [1:0]    fpu_typeTagOut;
  logic          fpu_wflags;
  logic [1:0]    fpu_typ;
  logic [1:0]    fpu_fmt;
  logic [2:0]    fpu_rm;
  logic          vpu_vill;
  logic          vpu_vma;
  logic          vpu_vta;
  logic [1:0]    vpu_vsew;
  logic [2:0]    vpu_vlmul;
  logic          vpu_specVill;
  logic          vpu_specVma;
  logic          vpu_specVta;
  logic [1:0]    vpu_specVsew;
  logic [2:0]    vpu_specVlmul;
  logic          vpu_vm;
