  logic [6:0]    numWB;
  logic [2:0]    commitType;
  logic          srcState_0;
  logic          srcState_1;
  logic          srcState_2;
  logic          srcState_3;
  logic          srcState_4;
  logic [1:0]    srcLoadDependency_0_0;
  logic [1:0]    srcLoadDependency_0_1;
  logic [1:0]    srcLoadDependency_0_2;
