  // END GENERATED

endpackage

// ---------------------------------------------------------------------------
// 【节 2】xs_NewDispatch_core —— 可读核（选队列网络 + 全部状态）
// ---------------------------------------------------------------------------
module xs_NewDispatch_core
  import newdispatch_pkg::*;
(
  input  logic                      clock,
  input  logic                      reset,

  // 来自 Rename 的「预览」通道：只有 valid/fuType/fuOpType，比 fromRename 早一拍用来选 IQ
  input  logic [RENAME_W-1:0]                  renameIn_valid,
  input  logic [RENAME_W-1:0][FUTYPE_W-1:0]    renameIn_fuType,

  // 各 exu 当前占用条目数；索引 7 和 17 在 golden 里被 DCE 掉了，这里保留完整 25 列，
  // 由 wrapper 把不存在的两列钉死（见 wrapper 里的说明）
  input  logic [EXU_NUM-1:0][4:0]              iqValidNum,

  // 握手
  input  logic                                 toRenameAllFire, // 6 条全部 fire（scalar，不是 per-lane）
  input  logic [RENAME_W-1:0]                  firedVec,        // 每条 lane 本拍 fire
  input  logic [IQ_NUM-1:0]                    iqReady,         // 每个 IQ 的 ready（golden 只取每 IQ 第 0 个 enq 口）

  // 选择结果
  output logic [RENAME_W-1:0][IQ_NUM-1:0]      uopSelIQ_o,      // 每条 lane 选中的 IQ（one-hot）
  output logic [RENAME_W-1:0][IQ_NUM-1:0][2:0] uopSelIQMatrix_o,// 前缀计数矩阵
  output logic [RENAME_W-1:0]                  uopBlockByIQ_o   // 该 lane 被目标 IQ 堵住
);

  // -------------------------------------------------------------------------
  // 【节 2.1】fuType 归组（组合）
  // -------------------------------------------------------------------------
  // golden: fuTypeOH_<lane>_<g> = (fuType[b1]|fuType[b2]|...) & renameIn_valid
  //         fuTypeOHSingle_<lane>_<s> 同理
  logic [RENAME_W-1:0][MULTI_G-1:0]  fuTypeOH;
  logic [RENAME_W-1:0][SINGLE_G-1:0] fuTypeOHSingle;

  always_comb begin
    for (int l = 0; l < RENAME_W; l++) begin
      for (int g = 0; g < MULTI_G; g++)
        fuTypeOH[l][g] = |(renameIn_fuType[l] & G_FUMASK[g]) & renameIn_valid[l];
      for (int s = 0; s < SINGLE_G; s++)
        fuTypeOHSingle[l][s] = |(renameIn_fuType[l] & S_FUMASK[s]) & renameIn_valid[l];
    end
  end

  // -------------------------------------------------------------------------
  // 【节 2.2】compareMatrix / IQSort —— 按占用数给同组 IQ 排名
  // -------------------------------------------------------------------------
  // compareMatrix[g][i][j] = 「第 i 个 exu 比第 j 个空」。对角线恒 0，下三角取上三角取反
  // （golden 就是这么写的：compareMatrix_x_1_0 = ~compareMatrix_x_0_1，不是重新比一次）。
  // IQSort[g][rank][i] = 「第 i 个 exu 排第 rank 名」，rank 0 = 最空。
  // golden: IQSort_x_<rank>_<i> <= PopCount(compareMatrix[i]) == (iqNum-1-rank)
  // ★IQSort 是不带复位的寄存器★（golden 在 always @(posedge clock) 里，无 reset 分支）。
  // ★已知 FM 隐患（phase 2 必须处理）★：这里为了写成一个规整的 10×4×4 阵列，
  // iqNum<4 的组会留下永远不写也不读的 iqSort 位。仿真无害（从不被索引），但 FM
  // 会把它们算成 impl 侧多出来的死寄存器 → unread 点。真跑 FM 前要么按 G_IQNUM
  // 拆成每组精确尺寸，要么给出对称双射证明，不能靠 waiver 掩过去。
  logic [MULTI_G-1:0][3:0][3:0] compareMatrix;
  logic [MULTI_G-1:0][3:0][3:0] iqSort;

  always_comb begin
    compareMatrix = '0;
    for (int g = 0; g < MULTI_G; g++)
      for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
          if (i < G_IQNUM[g] && j < G_IQNUM[g]) begin
            if (i == j)      compareMatrix[g][i][j] = 1'b0;
            else if (i < j)  compareMatrix[g][i][j] =
                               iqValidNum[G_EXU[g][i]] < iqValidNum[G_EXU[g][j]];
            else             compareMatrix[g][i][j] =
                               ~(iqValidNum[G_EXU[g][j]] < iqValidNum[G_EXU[g][i]]);
          end
  end

  always_ff @(posedge clock) begin   // 无复位：照抄 golden
    for (int g = 0; g < MULTI_G; g++)
      for (int r = 0; r < 4; r++)
        for (int i = 0; i < 4; i++)
          if (r < G_IQNUM[g] && i < G_IQNUM[g])
            iqSort[g][r][i] <= ($countones(compareMatrix[g][i]) == (G_IQNUM[g] - 1 - r));
  end

  // -------------------------------------------------------------------------
  // 【节 2.3】minIQSel —— 第 lane 条 uop 在本组里取第 (lane % iqNum) 名
  // -------------------------------------------------------------------------
  // 这一步是「同拍内分散」：6 条 lane 若都是 alu，就分别取第 0/1/2/3/0/1 名，
  // 而不是全挤到最空的那一个。golden: minIQSel_x_<lane>_<iq> = IQSort_x_<lane%iqNum>_<k>
  logic [MULTI_G-1:0][RENAME_W-1:0][IQ_NUM-1:0] minIQSelAll;

  always_comb begin
    minIQSelAll = '0;
    for (int g = 0; g < MULTI_G; g++)
      for (int l = 0; l < RENAME_W; l++)
        for (int k = 0; k < 4; k++)
          if (k < G_IQNUM[g])
            minIQSelAll[g][l][G_IQ[g][k]] = iqSort[g][l % G_IQNUM[g]][k];
  end

  // -------------------------------------------------------------------------
  // 【节 2.4】popFuTypeOH —— 本 lane 之前有几条 uop 也要进同一组
  // -------------------------------------------------------------------------
  // golden: popFuTypeOH_<lane>_<g> = PopCount(fuTypeOH[0..lane-1][g])，3 位宽。
  logic [RENAME_W-1:0][MULTI_G-1:0][2:0] popFuTypeOH;

  always_comb begin
    popFuTypeOH = '0;
    for (int l = 1; l < RENAME_W; l++)
      for (int g = 0; g < MULTI_G; g++) begin
        automatic logic [2:0] cnt = '0;
        for (int p = 0; p < l; p++) cnt += 3'(fuTypeOH[p][g]);
        popFuTypeOH[l][g] = cnt;
      end
  end

  // -------------------------------------------------------------------------
  // 【节 2.5】uopSelIQ —— 不复位的选择寄存器，两个写源，装入优先于清除
  // -------------------------------------------------------------------------
  // golden 展开（always @(posedge clock)，**无复位**）：
  //   if (toRenameAllFire)  uopSelIQ <= 本拍新选择
  //   else                  uopSelIQ <= ~firedVec[lane] & uopSelIQ
  // 对应 Chisel 的 when(toRenameAllFire){...}.elsewhen(fromRename(i).fire){ u := 0 }
  // —— golden 把 elsewhen+保持合成了一个 AND，语义一致。
  // ★优先级：toRenameAllFire 分支胜★（两个写源同时成立时按新选择装入，不清零）。
  //
  // ★golden 陷阱（必须照抄）★：Mux1H 选出的 6 元素向量被一个 **3 位**索引
  // （popFuTypeOH，0..7）读，firtool 把它补成 8 项，第 6、7 项填的是**第 0 项**
  // （不是 0，也不是 mod 6 回绕）。索引实际到不了 6/7（PopCount 最多 5），所以是
  // 无关项；但 FM 证不出不可达，写法不同就会多出失配点，故这里显式照抄 8 项形状。
  logic [RENAME_W-1:0][IQ_NUM-1:0] uopSelIQ;

  always_ff @(posedge clock) begin   // 无复位：照抄 golden
    for (int l = 0; l < RENAME_W; l++) begin
      if (toRenameAllFire) begin
        for (int q = 0; q < IQ_NUM; q++) begin
          automatic logic [7:0] lanes;   // 8 项：0..5 是真 lane，6/7 复制第 0 项
          automatic logic [2:0] idx;
          automatic logic       multi;
          automatic logic       single;
          lanes = '0;
          idx   = '0;
          multi = 1'b0;
          single = 1'b0;
          for (int g = 0; g < MULTI_G; g++) begin
            multi |= fuTypeOH[l][g];
            idx   |= fuTypeOH[l][g] ? popFuTypeOH[l][g] : 3'd0;   // Mux1H
            for (int p = 0; p < RENAME_W; p++)
              lanes[p] |= fuTypeOH[l][g] & minIQSelAll[g][p][q];  // Mux1H over groups
          end
          lanes[6] = lanes[0];   // ← golden 的补位：第 0 项，不是 0
          lanes[7] = lanes[0];
          for (int s = 0; s < SINGLE_G; s++)
            single |= fuTypeOHSingle[l][s] & (S_IQ[s] == q);
          uopSelIQ[l][q] <= renameIn_valid[l] & (multi ? lanes[idx] : single);
        end
      end else begin
        for (int q = 0; q < IQ_NUM; q++)
          uopSelIQ[l][q] <= ~firedVec[l] & uopSelIQ[l][q];
      end
    end
  end

  // -------------------------------------------------------------------------
  // 【节 2.6】uopSelIQMatrix / uopBlockByIQ —— 前缀计数定「第几个入队口」
  // -------------------------------------------------------------------------
  // uopSelIQMatrix[lane][iq] = PopCount(uopSelIQ[0..lane][iq])。
  // 于是「该 IQ 第 n 个入队口取哪条 lane」= 该列上计数恰好等于 n+1 的第一条 lane。
  // uopBlockByIQ：目标 IQ 这拍收不下就把该 lane 堵住；ready 时只能收 numEnq(=2) 个。
  logic [RENAME_W-1:0][IQ_NUM-1:0][2:0] uopSelIQMatrix;
  logic [RENAME_W-1:0][IQ_NUM-1:0]      uopBlockMatrix;

  always_comb begin
    for (int l = 0; l < RENAME_W; l++)
      for (int q = 0; q < IQ_NUM; q++) begin
        automatic logic [2:0] cnt = '0;
        for (int p = 0; p <= l; p++) cnt += 3'(uopSelIQ[p][q]);
        uopSelIQMatrix[l][q] = cnt;
        uopBlockMatrix[l][q] = iqReady[q] ? (cnt > 3'd2) : (|cnt);
      end
  end

  always_comb
    for (int l = 0; l < RENAME_W; l++)
      uopBlockByIQ_o[l] = |uopBlockMatrix[l];

  assign uopSelIQ_o       = uopSelIQ;
  assign uopSelIQMatrix_o = uopSelIQMatrix;

endmodule

// ---------------------------------------------------------------------------
// 【节 3】NewDispatch —— 与 golden 逐位同名的 wrapper（7725 端口）
// ---------------------------------------------------------------------------
// 端口表由 scripts/gen_newdispatch.py 从 golden 原文派生，顺序/方向/位宽逐字一致。
// 端口表里有两类「洞」，都是 firtool DCE 的结果，**必须照抄，不能补齐**：
//   * io_IQValidNumVec_7 / _17 不存在（这两个 exu 从没参与过任何 compareMatrix）
//   * io_toIssueQueues_<odd>_ready 不存在（golden 每个 IQ 只读第 0 个 enq 口的 ready）
//   * io_perf_4_value 不存在（Chisel 里 "dispatch_stall_cycle_lsq" 是常量 false.B）
//   * io_fromRename_<1..5>_bits_snapshot / io_enqRob_req_<1..5>_bits_snapshot 不存在
//   * io_toIssueQueues_8..19 没有 srcLoadDependency（浮点/向量 IQ 不吃 load 唤醒依赖）
//
// ★未追清 / 未实现清单（本文件当前状态）★
//   a. 7 个子模块本仓**一个都没有实现**，golden 里它们是真逻辑，不是厂商宏：
//      RegCacheTagTable(1391) BusyTable(21579) BusyTable_1(2854) BusyTable_2(1539)
//      BusyTable_3(443) VlBusyTable(1401) LsqEnqCtrl(2595)   —— 共 31802 行
//   b. 因此 dyninst_t 里那 46 个「增值」字段（srcState / srcLoadDependency /
//      useRegCache / regCacheIdx / lqIdx / sqIdx / storeSetHit / ssid /
