  assign core_iqValidNum[24] = io_IQValidNumVec_24;

  // golden 每个 IQ 只读第 0 个 enq 口的 ready（奇数号 ready 端口被 DCE）。
  assign core_iqReady[ 0] = io_toIssueQueues_0_ready;
  assign core_iqReady[ 1] = io_toIssueQueues_2_ready;
  assign core_iqReady[ 2] = io_toIssueQueues_4_ready;
